require_once __DIR__ . '/api/lib/owner-lab-store-drafts-v1.php';
require_once __DIR__ . '/api/config/admin-authorization.php';

function draft_test_assert(bool $condition, string $label): void { if (!$condition) throw new RuntimeException('FAIL: ' . $label); echo 'PASS: ' . $label . PHP_EOL; }
function draft_test_input(string $key, array $overrides = []): array { return array_merge(['title'=>'League banner','category'=>'League presentation','description'=>'Private preparation only','media_reference'=>'/public/img/banner.png','idempotency_key'=>$key],$overrides); }
function draft_test_manifest_sha(string $path): string { $contents = file_get_contents($path); if (!is_string($contents)) throw new RuntimeException('migration unreadable'); return hash('sha256', str_replace("\r\n", "\n", $contents)); }
$readGate='NARRRFS_OWNER_LAB_STORE_DRAFTS_READ_ENABLED';
$writeGate='NARRRFS_OWNER_LAB_STORE_DRAFTS_WRITE_ENABLED';
$oldRead=getenv($readGate);$oldWrite=getenv($writeGate);putenv($readGate.'=1');putenv($writeGate.'=1');
$policyFile=__DIR__.'/api/config/admin-route-policies.php';
$policies=require $policyFile;
$owner='12345678901234567';$now=2000000000;
$session=['discord_id'=>$owner,NARRRFS_ADMIN_PROVENANCE_SESSION_KEY=>NARRRFS_ADMIN_AUTH_PROVENANCE,NARRRFS_ADMIN_AUTH_ISSUED_AT_SESSION_KEY=>$now,NARRRFS_ADMIN_AUTH_LAST_SEEN_AT_SESSION_KEY=>$now,NARRRFS_ADMIN_AUTH_EXPIRES_AT_SESSION_KEY=>$now+NARRRFS_ADMIN_AUTH_ABSOLUTE_SECONDS];
