draft_test_assert(narrrfs_admin_authorization_decision($readPolicy,[],['method'=>'GET'],[$owner],$now)['status']===401,'anonymous draft read rejects before database access');
draft_test_assert(narrrfs_admin_authorization_decision($readPolicy,$session,['method'=>'POST'],[$owner],$now)['status']===405,'read policy rejects mutations before database access');
draft_test_assert(narrrfs_admin_authorization_decision($writePolicy,$session,['method'=>'POST','contentType'=>'application/json','origin'=>'https://narrrfs.world','csrfToken'=>'bad'],[$owner],$now)['status']===403,'invalid CSRF rejects before database access');
draft_test_assert(narrrfs_admin_authorization_decision($writePolicy,$session,['method'=>'POST','contentType'=>'application/json','origin'=>'https://attacker.invalid','csrfToken'=>'bad'],[$owner],$now)['status']===403,'wrong origin rejects before database access');
$csrfSession=$session;$csrfToken=narrrfs_issue_admin_csrf_token($csrfSession,$now,static fn(int $bytes):string=>str_repeat('a',$bytes),'owner_control.lab_store_drafts.create.v1');$csrfDecision=narrrfs_admin_authorization_decision($writePolicy,$csrfSession,['method'=>'POST','contentType'=>'application/json','origin'=>'https://narrrfs.world','csrfToken'=>$csrfToken],[$owner],$now);draft_test_assert($csrfDecision['allowed']===true&&$csrfDecision['consumeCsrf']===true,'valid one-time CSRF authorizes exactly one draft mutation request');narrrfs_consume_admin_csrf($csrfSession,true);draft_test_assert(narrrfs_admin_authorization_decision($writePolicy,$csrfSession,['method'=>'POST','contentType'=>'application/json','origin'=>'https://narrrfs.world','csrfToken'=>$csrfToken],[$owner],$now)['status']===403,'consumed one-time CSRF rejects replay before database access');
putenv($readGate);$disabledPolicies=require $policyFile;$disabledPolicy=$disabledPolicies['routes']['owner_control.lab_store_drafts.read.v1'];draft_test_assert(narrrfs_admin_authorization_decision($disabledPolicy,$session,['method'=>'GET'],[$owner],$now)['status']===404,'disabled policy rejects before database access');putenv($readGate.'=1');
$path=tempnam(sys_get_temp_dir(),'lab-store-drafts-'); if($path===false)throw new RuntimeException('temp unavailable'); $db=new SQLite3($path);$db->enableExceptions(true);
try {
  foreach(['tbl_mouse_lp_store_offers','tbl_mouse_lp_store_purchases','tbl_mousefight_league_point_spends','tbl_user_scores','tbl_score_adjustments','tbl_user_inventory','tbl_user_genetic_items','tbl_genetic_item_history','tbl_store_items','tbl_genetic_trait_catalog'] as $table){$db->exec("CREATE TABLE $table (id INTEGER PRIMARY KEY)");foreach(['INSERT','UPDATE','DELETE'] as $verb)$db->exec("CREATE TRIGGER protect_{$table}_$verb BEFORE $verb ON $table BEGIN SELECT RAISE(ABORT,'protected table write'); END;");}
  $sql=file_get_contents(__DIR__.'/db/migrations/20261107_owner_control_lab_store_drafts_m1.sql');draft_test_assert(is_string($sql)&&$sql!=='','draft migration is readable');$db->exec($sql);$m11=file_get_contents(__DIR__.'/db/migrations/20261109_owner_control_lab_store_drafts_m11.sql');draft_test_assert(is_string($m11)&&$m11!=='','M1.1 migration is readable');$db->exec($m11);
  $manifest=file_get_contents(__DIR__.'/db/migrations/manifest-v1.txt');$sha=draft_test_manifest_sha(__DIR__.'/db/migrations/20261107_owner_control_lab_store_drafts_m1.sql');draft_test_assert(is_string($manifest)&&str_contains($manifest,'owner-control-lab-store-drafts-m1-20261107|20261107_owner_control_lab_store_drafts_m1.sql|'.$sha),'draft migration checksum matches manifest');
  $actor='12345678901234567';$created=narrrfs_lab_store_draft_write($db,draft_test_input('aaaaaaaaaaaaaaaaaaaaaaaa'),'12345678901234567',false);draft_test_assert($created['replayed']===false&&($created['draft']['version']??0)===1,'create commits one version-one private draft');$id=$created['draft']['draft_id'];
  $replay=narrrfs_lab_store_draft_write($db,draft_test_input('aaaaaaaaaaaaaaaaaaaaaaaa'),$actor,false);draft_test_assert($replay['replayed']===true&&$replay['draft_id']===$id&&$replay['version']===1,'same actor and payload retry replays minimal result');
  $reused=false;try{narrrfs_lab_store_draft_write($db,draft_test_input('aaaaaaaaaaaaaaaaaaaaaaaa',['title'=>'Different']),$actor,false);}catch(NarrrfsOwnerLabStoreDraftException $e){$reused=$e->publicCode()==='idempotency_key_reused';}draft_test_assert($reused,'same key with a changed payload rejects');
  $db->exec("UPDATE tbl_owner_control_lab_store_draft_receipts SET expires_at='2000-01-01 00:00:00' WHERE draft_id=$id");$expired=false;try{narrrfs_lab_store_draft_write($db,draft_test_input('aaaaaaaaaaaaaaaaaaaaaaaa'),$actor,false);}catch(NarrrfsOwnerLabStoreDraftException $e){$expired=$e->publicCode()==='idempotency_key_expired';}draft_test_assert($expired&&(int)$db->querySingle('SELECT COUNT(*) FROM tbl_owner_control_lab_store_drafts')===1,'expired receipt cannot replay or create a second draft');
  $updated=narrrfs_lab_store_draft_write($db,draft_test_input('bbbbbbbbbbbbbbbbbbbbbbbb',['draft_id'=>$id,'expected_version'=>1,'title'=>'Updated banner']),$actor,true);draft_test_assert($updated['replayed']===false&&$updated['draft']['version']===2,'expected-version update increments once');
  $stale=false;try{narrrfs_lab_store_draft_write($db,draft_test_input('cccccccccccccccccccccccc',['draft_id'=>$id,'expected_version'=>1]),$actor,true);}catch(NarrrfsOwnerLabStoreDraftException $e){$stale=$e->publicCode()==='version_conflict';}draft_test_assert($stale,'stale update has no mutation');
  $foreign=false;try{narrrfs_lab_store_draft_write($db,draft_test_input('dddddddddddddddddddddddd',['media_reference'=>'https://outside.invalid/a.png']),$actor,false);}catch(NarrrfsOwnerLabStoreDraftException $e){$foreign=$e->publicCode()==='invalid_media_reference';}draft_test_assert($foreign,'external media reference rejects before transaction');
  draft_test_assert((int)$db->querySingle('SELECT COUNT(*) FROM tbl_owner_control_lab_store_drafts')===1&&(int)$db->querySingle('SELECT COUNT(*) FROM tbl_owner_control_lab_store_draft_audit')===2&&(int)$db->querySingle('SELECT COUNT(*) FROM tbl_owner_control_lab_store_draft_receipts')===2,'draft, immutable audit and bounded receipts are independent');
  foreach(['tbl_mouse_lp_store_offers','tbl_mouse_lp_store_purchases','tbl_mousefight_league_point_spends','tbl_user_scores','tbl_score_adjustments','tbl_user_inventory','tbl_user_genetic_items','tbl_genetic_item_history','tbl_store_items','tbl_genetic_trait_catalog'] as $table)draft_test_assert((int)$db->querySingle("SELECT COUNT(*) FROM $table")===0,'no side effect on '.$table);
  $db->exec("CREATE TRIGGER fail_draft_audit BEFORE INSERT ON tbl_owner_control_lab_store_draft_audit WHEN NEW.action='created' BEGIN SELECT RAISE(ABORT,'forced'); END;");$rollback=false;try{narrrfs_lab_store_draft_write($db,draft_test_input('eeeeeeeeeeeeeeeeeeeeeeee'),$actor,false);}catch(Throwable){$rollback=true;}draft_test_assert($rollback&&(int)$db->querySingle('SELECT COUNT(*) FROM tbl_owner_control_lab_store_drafts')===1,'forced audit failure rolls draft transaction back');
  echo "PASS: Lab Store M1 disposable draft transaction suite\n";
} finally {$db->close();@unlink($path);}
$oldRead===false?putenv($readGate):putenv($readGate.'='.$oldRead);$oldWrite===false?putenv($writeGate):putenv($writeGate.'='.$oldWrite);
